CREATE TABLE IF NOT EXISTS foods (
  food_code TEXT PRIMARY KEY,
  category TEXT,
  name_zh TEXT NOT NULL,
  name_en TEXT,
  edible_rate NUMERIC,
  water NUMERIC,
  energy_kcal NUMERIC,
  energy_kj NUMERIC,
  protein NUMERIC,
  fat NUMERIC,
  carb NUMERIC,
  dietary_fiber NUMERIC,
  cholesterol NUMERIC,
  ash NUMERIC,
  vitamin_a NUMERIC,
  carotene NUMERIC,
  retinol NUMERIC,
  thiamin NUMERIC,
  riboflavin NUMERIC,
  niacin NUMERIC,
  vitamin_c NUMERIC,
  vitamin_e NUMERIC,
  calcium NUMERIC,
  phosphorus NUMERIC,
  potassium NUMERIC,
  sodium NUMERIC,
  magnesium NUMERIC,
  iron NUMERIC,
  zinc NUMERIC,
  selenium NUMERIC,
  copper NUMERIC,
  manganese NUMERIC,
  gi NUMERIC,
  remark TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_foods_category ON foods(category);
CREATE INDEX IF NOT EXISTS idx_foods_name_zh ON foods USING gin (name_zh gin_trgm_ops);

